#!/usr/bin/env node
// Bundle the Desktop Code view's transcript for the kernel's `/web` page
// (omp: packages/coding-agent/src/web-ui/assets/vendor/). The page drives one CLI
// session from a browser on the LAN and renders it with Desktop's own chat
// components, so it looks like this app. This script only reads `src/`:
// nothing here changes how Desktop itself is built or runs.
//
//   node scripts/build-web-ui.mjs [outDir]
//
// Writes `desktop-ui.js` (React production, marked + hljs with
// app/marked-setup.js's escaping, the pure app/ modules, design/ui and
// design/chat, JSX compiled the way build-frontend.mjs does) and
// `desktop-ui.css` (tokens, chat and composer layout, highlight theme).
// Left out: Babel, xterm, KaTeX and Mermaid (math and diagrams show as their
// source, as the components already do when those libraries are absent),
// and the web fonts (the CSS font stacks fall back to system fonts).
// Re-run it after a Desktop UI change, then rebuild `npi`.
import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const src = join(root, "src");
const outDir = resolve(process.argv[2] ?? join(root, "..", "omp", "packages", "coding-agent", "src", "web-ui", "assets", "vendor"));
const Babel = createRequire(import.meta.url)(join(src, "babel.min.js"));

// Scripts are taken from index.html in its order (the order is the dependency
// graph), up to the last chat component; then the extras the page needs.
const LAST = "design/chat/chat-view.jsx";
// Loaded later in index.html but needed here: the pure RPC-to-UI transforms
// (adapter.js and what it reads) and the composer's queue strip.
const EXTRA = ["model-names.js", "app/turn-status.js", "app/transcript-merge.js", "adapter.js", "design/queue-strip.jsx"];
const SKIP = new Set([
  "babel.min.js",
  "xterm.js",
  "xterm-addon-fit.js",
  "katex.min.js",
  "mermaid.min.js",
]);
const SWAP = { "react.development.js": "react.production.js", "react-dom.development.js": "react-dom.production.js" };

const html = readFileSync(join(src, "index.html"), "utf8");
const listed = [...html.matchAll(/<script\b[^>]*\ssrc="([^"]+)"[^>]*><\/script>/g)].map(m => m[1]);
const end = listed.indexOf(LAST);
if (end === -1) throw new Error(`index.html no longer loads ${LAST}`);
const scripts = [...listed.slice(0, end + 1), ...EXTRA.filter(path => !listed.slice(0, end + 1).includes(path))]
  .filter(path => !SKIP.has(path))
  .map(path => SWAP[path] ?? path);

const parts = [];
let jsx = 0;
for (const path of scripts) {
  let code = readFileSync(join(src, path), "utf8");
  if (path.endsWith(".jsx")) {
    code = Babel.transform(code, {
      filename: path,
      presets: ["react", "env"],
      plugins: ["transform-class-properties", "transform-object-rest-spread", "transform-flow-strip-types"],
      targets: { browsers: undefined },
      sourceMaps: false,
    }).code;
    jsx++;
  }
  // Each file ran as its own classic script in Desktop; one block per file
  // keeps an error in one from hiding which file it came from.
  parts.push(`/* ── ${path} ── */\n${code.replace(/\/\/# sourceMappingURL=\S+\s*$/, "")}\n`);
}

// CSS: the token sheet plus the layout partials the transcript and composer use.
const CSS = [
  "design/styles.css",
  "design/layout/chrome.css",
  "design/layout/stage.css",
  "design/layout/chat.css",
  "design/layout/plan-edit.css",
  "design/layout/work-box.css",
  "design/layout/ask.css",
  "design/layout/ask-form.css",
  "design/layout/generative-ui.css",
  "design/layout/generative-ui-display.css",
  "design/layout/composer.css",
  "design/layout/goal.css",
  "design/layout/overlays.css",
  "design/layout/lightbox.css",
  "design/layout/file-preview.css",
  "design/layout/subagents.css",
  "design/layout/shell.css",
  "platform.css",
  "highlight-theme.css",
  "design/rich-content.css",
];
const css = CSS.map(path => {
  const text = readFileSync(join(src, path), "utf8")
    // No web fonts in the bundle: drop their faces, the stacks fall back.
    .replace(/@font-face\s*\{[^}]*\}\s*/g, "");
  if (/@import|url\((?!\s*["']?data:)/i.test(text)) throw new Error(`${path}: imports or references a file the bundle does not carry`);
  return `/* ── ${path} ── */\n${text}\n`;
}).join("");

let commit = "unknown";
try {
  commit = execFileSync("git", ["-C", root, "rev-parse", "--short", "HEAD"], { encoding: "utf8" }).trim();
} catch { /* not a checkout */ }
const version = JSON.parse(readFileSync(join(root, "src-tauri", "tauri.conf.json"), "utf8")).version;
const header = `/*! Generated by desktop/scripts/build-web-ui.mjs from NPi Desktop ${version} (${commit}). Do not edit; re-run the script.
 * Bundles React (MIT), marked (MIT), highlight.js (BSD-3-Clause) and NPi Desktop's chat components. */\n`;

mkdirSync(outDir, { recursive: true });
const js = header + parts.join("");
writeFileSync(join(outDir, "desktop-ui.js"), js);
writeFileSync(join(outDir, "desktop-ui.css"), header + css);
console.log(`desktop-ui.js: ${scripts.length} scripts (${jsx} JSX), ${(js.length / 1024).toFixed(0)} KB`);
console.log(`desktop-ui.css: ${CSS.length} sheets, ${(css.length / 1024).toFixed(0)} KB`);
console.log(`→ ${outDir}`);
